/bin/bash -lc "cd [workspace path] && python -c \"
import numpy as np
from scipy import ndimage
d = np.load('source_pixels.npz')['rgb'].astype(int)
med=np.median(d,axis=0); dist=np.abs(d-med).sum(-1)
prev_c=None
for t in range(0,51):
    m=dist[t]>60
    lab,n=ndimage.label(m)
    objs=ndimage.find_objects(lab)
    best=None
    for i,s in enumerate(objs,1):
        sz=(lab[s]==i).sum()
        if sz<8: continue
        ys,xs=np.where(lab==i)
        cx,cy=xs.mean(),ys.mean()
        if prev_c is None:
            if best is None or sz>best[0]: best=(sz,cx,cy,xs.min(),xs.max(),ys.min(),ys.max())
        else:
            dd=(cx-prev_c[0])**2+(cy-prev_c[1])**2
            if best is None or dd<best[0]: best=(dd,cx,cy,xs.min(),xs.max(),ys.min(),ys.max(),sz)
    if best:
        if prev_c is None: prev_c=(best[1],best[2]); print(t,'sz',best[0],'c',round(best[1],1),round(best[2],1),'bbox',best[3:])
        else: prev_c=(best[1],best[2]); print(t,'sz',best[7],'c',round(best[1],1),round(best[2],1),'bbox',best[3:7])
\""
